// Combine all RSS feeds and extract items
const feeds = $input.all();
const items = [];

for (const feed of feeds) {
  const xml = feed.json.data || feed.json.body || '';

  // Simple RSS item extraction via regex
  const itemRegex = /<item[^>]*>([\s\S]*?)<\/item>/gi;
  const titleRegex = /<title[^>]*>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/title>/i;
  const linkRegex = /<link[^>]*>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/link>/i;
  const descRegex = /<description[^>]*>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/description>/is;
  const pubDateRegex = /<pubDate[^>]*>(.*?)<\/pubDate>/i;

  let match;
  while ((match = itemRegex.exec(xml)) !== null) {
    const itemXml = match[1];
    const title = (titleRegex.exec(itemXml) || [])[1] || '';
    const link = (linkRegex.exec(itemXml) || [])[1] || '';
    const desc = (descRegex.exec(itemXml) || [])[1] || '';
    const pubDate = (pubDateRegex.exec(itemXml) || [])[1] || '';

    // Strip HTML from description
    const snippet = desc.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().substring(0, 300);

    if (title && link) {
      // Check if AI-related (basic keyword filter)
      const text = (title + ' ' + snippet).toLowerCase();
      const aiKeywords = ['ai', 'artificial intelligence', 'llm', 'gpt', 'claude', 'openai', 'anthropic', 'machine learning', 'deep learning', 'chatgpt', 'gemini', 'agent', 'latam', 'startup'];
      const hasAiKeyword = aiKeywords.some(kw => text.includes(kw));

      if (hasAiKeyword) {
        items.push({
          title: title.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#8217;/g, "'").replace(/&#8216;/g, "'").replace(/&#8220;/g, '"').replace(/&#8221;/g, '"'),
          url: link.trim(),
          snippet: snippet.substring(0, 200),
          published_at: pubDate,
          source: feed.json.url || 'unknown'
        });
      }
    }
  }
}

// Deduplicate by URL
const seen = new Set();
const unique = items.filter(item => {
  if (seen.has(item.url)) return false;
  seen.add(item.url);
  return true;
});

// Return top 10
return unique.slice(0, 10).map(item => ({ json: item }));

// Parse Claude responses and build summary
const items = $input.all();
const scored = [];

for (const item of items) {
  try {
    const response = item.json.message?.content || item.json.text || '';
    const parsed = JSON.parse(response);
    scored.push({
      title: item.json.title || 'Unknown',
      url: item.json.url || '',
      score: parsed.score || 0,
      classification: parsed.classification || 'discard',
      justification: parsed.justification || '',
      suggested_angle: parsed.suggested_angle || '',
      hook: parsed.hook || ''
    });
  } catch (e) {
    // Skip unparseable responses
  }
}

// Sort by score descending
scored.sort((a, b) => b.score - a.score);

// Build notification text
const topItems = scored.filter(s => s.score >= 50).slice(0, 5);
let summary = '🔍 AI Brief LATAM — Top Items\n\n';

for (let i = 0; i < topItems.length; i++) {
  const item = topItems[i];
  summary += `${i+1}. [${item.score}] ${item.classification.toUpperCase()}\n`;
  summary += `   ${item.title}\n`;
  summary += `   ${item.justification}\n`;
  summary += `   Hook: ${item.hook}\n`;
  summary += `   ${item.url}\n\n`;
}

if (topItems.length === 0) {
  summary += 'No high-scoring items found this cycle.\n';
}

return [{ json: { summary, scored, topItems } }];
